211	        Rollup.Snapshot before = rollup.snapshot(sheetId);
212	        claim.set(amount, dated, noteOf(note), corrects);
213	        claim.setRef(reference);
214	        List<String> tagged = tagsOf(tags);
215	        claim.setTags(tagged);
216	        useTags(sheetId, tagged);
