323	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the
324	     *  claim counts in no total, is not overdue, cannot be settled and no statement binds it. Refused for
325	     *  a claim that is not OPEN, a date not after today, and a claim dated inside a closed period. */
326	    @Transactional
327	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
328	        Claim claim = claims.findForUpdate(id, sheetId)
329	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
330	        refuseIfClosed(sheetId, claim.getDueBy());
331	        if (claim.getStatus() != ClaimStatus.OPEN) {
332	            throw new ResponseStatusException(HttpStatus.CONFLICT,
333	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
334	        }
335	        if (!until.isAfter(sheets.today(sheetId))) {
336	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
337	                    "A claim can only be deferred to a date after the sheet's today.");
338	        }
339	        Person person = person(sheetId, claim.getPersonId());
340	        Rollup.Snapshot before = rollup.snapshot(sheetId);
341	        claim.deferUntil(until);
342	        Claim saved = claims.saveAndFlush(claim);
343	        recordChange("CLAIM_DEFERRED", user, person, saved, saved.getNumber(), " until=" + until);
344	        rollup.recordChanges(user, before);
345	        return saved;
