553	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
554	        refuseIfClosed(sheetId, claim.getDueBy());
555	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
556	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
557	        }
558	        if (claim.getStatus() != ClaimStatus.SETTLED) {
559	            throw new ResponseStatusException(HttpStatus.CONFLICT,
560	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
561	        }
562	        Person person = person(sheetId, claim.getPersonId());
563	        BigDecimal old = claim.getSettledDue();
564	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim),
565	                settings.floor(sheetId, claim.getDate()), sheets.today(sheetId), grace(sheetId, person, claim),
566	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
567	        Rollup.Snapshot before = rollup.snapshot(sheetId);
568	        claim.setSettledDue(dueNow);
569	        logStatus(sheetId, user, person, claim);
570	        Claim saved = claims.saveAndFlush(claim);
571	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
572	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
573	        notifyWatchers(user, person, saved);
574	        rollup.recordChanges(user, before);
575	        return saved;
576	    }
577	
578	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
579	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
580	    @Transactional
581	    public Claim reject(String sheetId, String user, long id, String reason) {
582	        Claim claim = pending(sheetId, user, id);
583	        Person person = person(sheetId, claim.getPersonId());
584	        Rollup.Snapshot before = rollup.snapshot(sheetId);
585	        claim.setStatus(ClaimStatus.OPEN);
586	        logStatus(sheetId, user, person, claim);
587	        Claim saved = claims.saveAndFlush(claim);
588	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
589	        rollup.recordChanges(user, before);
590	        return saved;
591	    }
592	
593	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
594	     *  dated inside a closed period, or the user is not a steward of the sheet. */
595	    private Claim pending(String sheetId, String user, long id) {
596	        Claim claim = claims.findForUpdate(id, sheetId)
597	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
598	        refuseIfClosed(sheetId, claim.getDueBy());
599	        if (claim.getStatus() != ClaimStatus.PENDING) {
600	            throw new ResponseStatusException(HttpStatus.CONFLICT,
601	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
602	        }
603	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
604	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
605	        }
606	        return claim;
607	    }
608	
609	    /** How many days after its settlement a steward may still void a SETTLED claim. */
610	    private static final int VOID_SETTLED_DAYS = 7;
611	
612	    /** Refuse voiding a SETTLED claim unless the user is a steward of the sheet and the sheet's today is
613	     *  within {@value #VOID_SETTLED_DAYS} days of the claim's settlement, as its status log records it. */
614	    private void refuseUnlessSettledVoidable(String sheetId, String user, Claim claim) {
615	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
616	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a settled claim.");
617	        }
618	        LocalDate settledOn = claim.settledOn();
619	        LocalDate today = sheets.today(sheetId);
620	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
621	            throw new ResponseStatusException(HttpStatus.CONFLICT,
622	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
623	        }
624	    }
625	
626	    /** The permission matrix's action for each status a claim is moved to by opening, settling or voiding it. */
627	    private static final Map<ClaimStatus, String> ACTIONS = Map.of(
628	            ClaimStatus.OPEN, "open", ClaimStatus.SETTLED, "settle", ClaimStatus.PENDING, "settle",
629	            ClaimStatus.VOID, "void");
630	
631	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
632	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
633	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
634	
635	    private static String text(BigDecimal due) {
636	        return due == null ? "n/a" : due.toPlainString();
637	    }
638	
639	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
640	     *  today on or after the setting's date), the next of the claim's period (the one its due-by falls in), <period name>-<n>, or of
641	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
642	    private String nextNumber(String sheetId, Claim claim) {
643	        if (!isPeriodNumbering(sheetId)) {
644	            return Integer.toString(sheets.nextClaimNumber(sheetId));
645	        }
646	        Period period = periodOf(sheetId, claim.getDueBy());
647	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
648	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
649	    }
650	
651	    /** Whether the sheet's period numbering is in force: its today on or after the setting's date. */
652	    private boolean isPeriodNumbering(String sheetId) {
653	        LocalDate from = settings.periodNumberingFrom(sheetId);
654	        return from != null && !sheets.today(sheetId).isBefore(from);
655	    }
656	
657	    /** The sheet's period whose dates contain the date; null when none does. */
658	    private Period periodOf(String sheetId, LocalDate date) {
659	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
660	                .filter((p) -> p.contains(date)).findFirst().orElse(null);
661	    }
662	
663	    /** Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force
664	     *  on the claim's date: its person's grade's then when one is set, else the sheet's (a due of n/a, or
665	     *  no threshold, needs none). */
666	    private void refuseIfUnproven(String sheetId, Person person, Claim claim, BigDecimal due) {
667	        if (due == null || claim.getProofs() > 0) return;
668	        BigDecimal threshold = settings.proofThreshold(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
669	        if (threshold != null && due.compareTo(threshold) > 0) {
670	            throw new ResponseStatusException(HttpStatus.CONFLICT,
671	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
672	                            + "; add a proof before it is settled.");
673	        }
674	    }
675	
676	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
677	     *  on the claim's date (a due of n/a, or no threshold, needs none). */
678	    private void refuseIfUnnoted(String sheetId, Claim claim, BigDecimal due) {
679	        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) return;
680	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
681	        if (threshold != null && due.compareTo(threshold) > 0) {
682	            throw new ResponseStatusException(HttpStatus.CONFLICT,
683	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
684	                            + "; add a note before it is opened.");
685	        }
686	    }
687	
688	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
689	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
690	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
691	        BigDecimal limit = settings.clerkLimit(sheetId);
692	        return limit != null && due.compareTo(limit) > 0;
693	    }
694	
695	    /** Refuse a change to a claim whose due-by (the date given) is inside a closed period. The sheet is locked first, as closing
696	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
697	    private void refuseIfClosed(String sheetId, LocalDate date) {
698	        sheetRows.findForUpdate(sheetId);
699	        if (periods.isClosedOn(sheetId, date)) {
700	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim's due-by is inside a closed period.");
701	        }
702	    }
703	
704	    /** Refuse a reference another claim on the sheet (other than the one given) already carries, compared
705	     *  without regard to case; no reference is never refused. */
706	    private void refuseIfRefUsed(String sheetId, String ref, Long id) {
707	        if (ref != null && claims.refUsed(sheetId, ref, id)) {
708	            throw new ResponseStatusException(HttpStatus.CONFLICT,
709	                    "The reference '" + ref + "' is already used on this sheet.");
710	        }
711	    }
712	
713	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
714	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
715	        if (amount.signum() >= 0) return;
716	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
717	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
718	        if (!settled) {
719	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
720	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
721	        }
722	    }
723	
724	    /** Refuse a claim dated after its person's retirement date. */
725	    private static void refuseIfRetired(Person person, LocalDate date) {
726	        if (person.isRetiredOn(date)) {
727	            throw new ResponseStatusException(HttpStatus.CONFLICT,
728	                    "The claim is dated after " + person.getName() + " retired.");
729	        }
730	    }
731	
732	    private Person person(String sheetId, long personId) {
733	        return people.findByIdAndSheetId(personId, sheetId)
734	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
735	    }
736	
737	    /** What is due on the claim now: the due fixed when it was settled, else the greater of the floor in
738	     *  force on its date and its figure with the late charge on top while it is open and overdue (the charge
739	     *  is never bound by a statement; a correction has no floor); null when the figure is n/a. */
740	    public BigDecimal due(String sheetId, Person person, Claim claim) {
741	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), settings.floor(sheetId, claim.getDate()),
742	                sheets.today(sheetId), grace(sheetId, person, claim),
743	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
744	    }
745	
746	    /** The grace days of the person's grade in force on the claim's date, in force on that date; 0 when none. */
747	    private int grace(String sheetId, Person person, Claim claim) {
748	        return settings.dated(sheetId).graceOn(person.gradeOn(claim.getDate()), claim.getDate());
749	    }
750	
751	    /** The figure under the claim's due, before any late charge and floor: the due fixed when it was settled, else the figure
752	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
753	     *  null when that is n/a. */
754	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
755	        if (claim.getSettledDue() != null) return claim.getSettledDue();
756	        if (claim.isBound()) return claim.getStatedDue();
757	        return dueNow(sheetId, person, claim);
758	    }
759	
760	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
761	     *  force on that date, rounded as the claim's {@link Rounding} decides, before any late charge and
762	     *  floor; null when no rate of the grade applies by then. */
763	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
764	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
765	        if (rate == null) return null;
766	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
767	                rounding(sheetId, claim));
768	    }
769	
770	    /** How many claims a candidate rate would change and by how much in all. */
771	    public record RatePreview(int count, BigDecimal diff) {
772	    }
773	
774	    /** What a candidate percent for a grade, applied on every date, would do to the OPEN and PENDING claims of
775	     *  people on that grade on the claim's date: how many would show a different due, and the sum of new due
776	     *  less current due (an n/a due counting as 0.00). A claim bound by a statement does not change; nothing is saved. */
777	    @Transactional(readOnly = true)
778	    public RatePreview previewRate(String sheetId, Grade grade, BigDecimal pct) {
779	        Map<Long, Person> byId = new HashMap<>();
780	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) byId.put(p.getId(), p);
781	        int count = 0;
782	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
783	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
784	            if (!claim.getStatus().isOpen() || claim.isBound() || claim.getSettledDue() != null) continue;
785	            Person person = byId.get(claim.getPersonId());
786	            if (person == null || person.gradeOn(claim.getDate()) != grade) continue;
787	            RoundingMode rounding = rounding(sheetId, claim);
788	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
789	            BigDecimal next = LateCharge.dueOf(claim, figure, settings.floor(sheetId, claim.getDate()),
790	                    sheets.today(sheetId), grace(sheetId, person, claim), settings.dated(sheetId)::latePctOn, rounding);
791	            BigDecimal current = due(sheetId, person, claim);
792	            if (current != null && current.compareTo(next) == 0) continue;
793	            count++;
794	            diff = diff.add(next.subtract(current == null ? BigDecimal.ZERO : current));
795	        }
796	        return new RatePreview(count, diff.setScale(2));
797	    }
798	
799	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
800	     *  correction corrects, else by its own. */
801	    private RoundingMode rounding(String sheetId, Claim claim) {
802	        return rounding(sheetId, claim, sheets.today(sheetId));
803	    }
804	
805	    /** How the claim's figures round under the sheet's policy date with the date given standing in for
806	     *  the sheet's today. */
807	    public RoundingMode rounding(String sheetId, Claim claim, LocalDate today) {
808	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
809	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
810	                : null;
811	        return Rounding.of(Rounding.dateOf(claim, corrected),
812	                Rounding.policyDate(settings.policyDate(sheetId), today));
813	    }
814	
815	    /** The audit field of the reason a claim was voided with; blank when there is none. */
816	    private static String reasonField(String voidReason) {
817	        return voidReason == null ? "" : " reason=" + voidReason;
818	    }
819	
820	    /** Log the status the claim has just taken, with its due as worked out now. */
821	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
822	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
823	    }
824	
825	    private void recordChange(String event, String user, Person person, Claim claim) {
826	        recordChange(event, user, person, claim, claim.getNumber(), "");
827	    }
828	
829	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
830	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
831	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
832	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
833	                + (number == null ? "" : " number=" + number) + extra);
834	    }
835	
836	    /** Tell each user watching the person, in the order they started watching, that the claim was settled. */
837	    private void notifyWatchers(String user, Person person, Claim claim) {
838	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
839	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUserName()
840	                    + " person=" + person.getName() + " number=" + claim.getNumber());
841	        }
842	    }
843	
844	    private LocalDate dateOr(String sheetId, LocalDate date) {
845	        return date != null ? date : sheets.today(sheetId);
846	    }
847	
848	    /** The date a new claim given none takes: the sheet's entry date while it is set, else its today. */
849	    private LocalDate entryDateOr(String sheetId) {
850	        LocalDate entry = settings.entryDate(sheetId);
851	        return entry != null ? entry : sheets.today(sheetId);
852	    }
853	
854	    /** Every tag ever used on the sheet, by name. */
855	    @Transactional(readOnly = true)
856	    public List<String> tags(String sheetId) {
857	        return sheetTags.findBySheetIdOrderByNameAsc(sheetId).stream().map(SheetTag::getName).toList();
858	    }
859	
860	    /** Keep the tags as used on the sheet. */
861	    private void useTags(String sheetId, List<String> tagged) {
862	        for (String tag : tagged) {
863	            if (!sheetTags.existsBySheetIdAndName(sheetId, tag)) sheetTags.save(new SheetTag(sheetId, tag));
864	        }
865	    }
866	
867	    /** Tags as typed, comma separated: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
868	    public static List<String> tagsOf(String tags) {
869	        if (tags == null) return List.of();
870	        return Arrays.stream(tags.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
871	                .distinct().sorted().toList();
872	    }
873	
874	    /** A reference as given, trimmed; none when blank. */
875	    public static String refOf(String ref) {
876	        return ref == null || ref.isBlank() ? null : ref.trim();
877	    }
878	
879	    private static String noteOf(String note) {
880	        return note == null ? "" : note.trim();
881	    }
882	}
