324	package net.officefloor.hq.app.rollup;
325	
326	import java.math.BigDecimal;
327	import java.math.RoundingMode;
328	import java.time.LocalDate;
329	import java.util.ArrayList;
330	import java.util.LinkedHashMap;
331	import java.util.List;
332	import java.util.Map;
333	import java.util.Objects;
334	import net.officefloor.hq.app.Audit;
335	import net.officefloor.hq.app.claim.Claim;
336	import net.officefloor.hq.app.claim.ClaimRepository;
337	import net.officefloor.hq.app.claim.ClaimStatus;
338	import net.officefloor.hq.app.claim.LateCharge;
339	import net.officefloor.hq.app.claim.Rounding;
340	import net.officefloor.hq.app.person.Grade;
341	import net.officefloor.hq.app.person.Person;
342	import net.officefloor.hq.app.person.PersonRepository;
343	import net.officefloor.hq.app.rate.Rate;
344	import net.officefloor.hq.app.rate.RateRepository;
345	import net.officefloor.hq.app.setting.DatedSettings;
346	import net.officefloor.hq.app.setting.SettingService;
347	import net.officefloor.hq.app.setting.SheetSettingDatedRepository;
348	import net.officefloor.hq.app.setting.SheetSettingRepository;
349	import net.officefloor.hq.app.sheet.Sheet;
350	import net.officefloor.hq.app.sheet.SheetRepository;
351	import org.springframework.stereotype.Service;
352	
353	/**
354	 * The sheet's figures as the screen shows them: each person's claimed, due-total (late charges
355	 * included, held to the sheet's cap) and overdue-total (what is owed on their counting claims that are
356	 * open past their due-by, late charges included, skipping n/a), and the sheet's
357	 * claimed-total, due-total and overdue-total (the last two leaving out the single highest and lowest
358	 * person's figure when three or more people have one). A change takes a snapshot before it alters anything, then
359	 * {@link #recordChanges} audits, after the change's own lines, each person whose figures moved (in the
360	 * order they were added) and then the sheet's totals when they moved.
361	 */
362	@Service
363	public class Rollup {
364	
365	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
366	
367	    /** A person's figures; a null due-total is n/a. */
368	    record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
369	        boolean sameAs(Figures other) {
370	            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal)
371	                    && same(overdueTotal, other.overdueTotal);
372	        }
373	    }
374	
375	    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
376	    public record Snapshot(String sheetId, Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
377	            BigDecimal overdueTotal) {
378	    }
379	
380	    private final PersonRepository people;
381	    private final ClaimRepository claims;
382	    private final RateRepository rates;
383	    private final SheetRepository sheets;
384	    private final SheetSettingRepository settings;
385	    private final SheetSettingDatedRepository dated;
386	    private final Audit audit;
387	
388	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
389	            SheetSettingRepository settings, SheetSettingDatedRepository dated, Audit audit) {
390	        this.people = people;
391	        this.claims = claims;
392	        this.rates = rates;
393	        this.sheets = sheets;
394	        this.settings = settings;
395	        this.dated = dated;
396	        this.audit = audit;
397	    }
398	
399	    /** The sheet's figures as the store holds them now, within the caller's transaction. */
400	    public Snapshot snapshot(String sheetId) {
401	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
402	        // The floor and late percent are those in force on each claim's date; the cap that in force today.
403	        DatedSettings values = DatedSettings.of(dated, sheetId);
404	        BigDecimal cap = values.capOn(today);
405	        LocalDate policyDate = Rounding.policyDate(SettingService.policyDateOf(settings, sheetId), today);
406	        Map<Grade, List<Rate>> ratesByGrade = new LinkedHashMap<>();
407	        for (Rate rate : rates.findBySheetIdInOrder(sheetId)) {
408	            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
409	        }
410	        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
411	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
412	            claimsByPerson.computeIfAbsent(claim.getPersonId(), p -> new ArrayList<>()).add(claim);
413	        }
414	        Map<Long, Figures> figures = new LinkedHashMap<>();
415	        BigDecimal claimedTotal = ZERO;
416	        List<BigDecimal> dues = new ArrayList<>();
417	        List<BigDecimal> overdues = new ArrayList<>();
418	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
419	            Grade gradeToday = today == null ? null : person.gradeOn(today);
420	            BigDecimal claimed = ZERO;
421	            BigDecimal due = ZERO;
422	            BigDecimal overdue = ZERO;
423	            boolean keptFigure = false;
424	            List<Claim> theirs = claimsByPerson.getOrDefault(person.getId(), List.of());
425	            for (Claim claim : theirs) {
426	                if (!counts(person, claim, today)) continue;
427	                claimed = claimed.add(claim.getAmount());
428	                // A claim's live figure is at the grade in force on its date.
429	                Grade grade = person.gradeOn(claim.getDate());
430	                RoundingMode rounding = Rounding.of(Rounding.dateOf(claim, corrected(claim, theirs)), policyDate);
431	                BigDecimal figure = figure(claim, ratesByGrade.getOrDefault(grade, List.of()), rounding);
432	                int grace = values.graceOn(grade, claim.getDate());
433	                BigDecimal owed = LateCharge.dueOf(claim, figure, values.floorOn(claim.getDate()), today,
434	                        grace, values::latePctOn, rounding);
435	                if (owed != null) due = due.add(owed);
436	                if (owed != null && isOverdue(claim, grace, today)) overdue = overdue.add(owed);
437	                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) {
438	                    keptFigure = true;
439	                }
440	                // A live figure at a grade other than today's is not undone by today's grade having no rate.
441	                if (figure != null && grade != gradeToday) keptFigure = true;
442	                // Nor is a live figure on a claim dated by today undone by its rate having ended since.
443	                if (figure != null && today != null && !claim.getDate().isAfter(today)) keptFigure = true;
444	            }
445	            // n/a when no rate of the grade in force today is in force today and no claim keeps a figure.
446	            // Held to the sheet's cap; n/a is not capped.
447	            BigDecimal personDue = SettingService.capped((today == null
448	                    || Rate.inForce(ratesByGrade.getOrDefault(gradeToday, List.of()), today) == null) && !keptFigure
449	                            ? null : due, cap);
450	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
451	            claimedTotal = claimedTotal.add(claimed);
452	            if (personDue != null) dues.add(personDue);
453	            overdues.add(overdue);
454	        }
455	        return new Snapshot(sheetId, figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
456	    }
457	
458	    /** Audit, once the transaction commits, each person's due-total as it stood in the snapshot, in the
459	     *  order they were added. */
460	    public void recordSnapshot(String user, Snapshot before) {
461	        String prefix = " sheet=" + before.sheetId() + " by=" + user;
462	        before.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT" + prefix + " name="
463	                + figures.name() + " due-total=" + text(figures.dueTotal())));
464	    }
465	
466	    /** Audit, once the transaction commits, the figures that moved since the snapshot was taken. */
467	    public void recordChanges(String user, Snapshot before) {
468	        Snapshot after = snapshot(before.sheetId());
469	        String prefix = " sheet=" + before.sheetId() + " by=" + user;
470	        after.people().forEach((id, now) -> {
471	            if (!now.sameAs(before.people().get(id))) {
472	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + text(now.claimed())
473	                        + " due-total=" + text(now.dueTotal()) + " overdue-total=" + text(now.overdueTotal()));
474	            }
475	        });
476	        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
477	                || !same(before.overdueTotal(), after.overdueTotal())) {
478	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + text(after.claimedTotal())
479	                    + " due-total=" + text(after.dueTotal()) + " overdue-total=" + text(after.overdueTotal()));
480	        }
481	    }
482	
483	    /** Whether the claim is overdue: open and not deferred, with its due-by plus the grace days of its
484	     *  person's grade before the sheet's today. */
485	    private static boolean isOverdue(Claim claim, int grace, LocalDate today) {
486	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null
487	                && LateCharge.lateFrom(claim, grace).isBefore(today);
488	    }
489	
490	    /** Only open (PENDING included) and settled claims count toward what is claimed and due; a person's
491	     *  open claims dated within one of their holds, or all of them once their retirement date is reached,
492	     *  do not, unless a statement binds them; nor does a
493	     *  claim deferred on the sheet's today. */
494	    private static boolean counts(Person person, Claim claim, LocalDate today) {
495	        return claim.getStatus() == ClaimStatus.SETTLED
496	                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
497	                        && (claim.isBound() || !person.isLeftOut(claim.getDate(), today)));
498	    }
499	
500	    /** The claim's figure, as ClaimService.figure works it out: the settled due, else the stated due,
501	     *  (unless PENDING), else the rate figure at the grade's rate in force on its date, rounded as the claim rounds,
502	     *  before any late charge and floor; null when that is n/a. */
503	    private static BigDecimal figure(Claim claim, List<Rate> gradeRates, RoundingMode rounding) {
504	        if (claim.getSettledDue() != null) return claim.getSettledDue();
505	        if (claim.isBound()) return claim.getStatedDue();
506	        Rate rate = Rate.inForce(gradeRates, claim.getDate());
507	        if (rate == null) return null;
508	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, rounding);
509	    }
510	
511	    /** Of the person's claims, the one a correction corrects by number; null for any other claim. */
512	    private static Claim corrected(Claim claim, List<Claim> theirs) {
513	        if (!claim.isCorrection() || claim.getCorrects() == null) return null;
514	        for (Claim other : theirs) {
515	            if (claim.getCorrects().equals(other.getNumber())) return other;
516	        }
517	        return null;
518	    }
519	
520	    /** The sum of the figures, leaving out the single highest and the single lowest when there are three or more. */
521	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
522	        BigDecimal total = figures.stream().reduce(ZERO, BigDecimal::add);
523	        if (figures.size() < 3) return total;
524	        return total.subtract(figures.stream().max(BigDecimal::compareTo).get())
525	                .subtract(figures.stream().min(BigDecimal::compareTo).get());
526	    }
527	
528	    private static boolean same(BigDecimal a, BigDecimal b) {
529	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
530	    }
531	
532	    private static String text(BigDecimal figure) {
533	        return figure == null ? "n/a" : figure.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
534	    }
535	}
536	package net.officefloor.hq.app.person;
