538	import jakarta.persistence.CascadeType;
539	import jakarta.persistence.Column;
540	import jakarta.persistence.Entity;
541	import jakarta.persistence.FetchType;
542	import jakarta.persistence.GeneratedValue;
543	import jakarta.persistence.GenerationType;
544	import jakarta.persistence.Id;
545	import jakarta.persistence.JoinColumn;
546	import jakarta.persistence.OneToMany;
547	import jakarta.persistence.Table;
548	import jakarta.persistence.Version;
549	import java.time.LocalDate;
550	import java.util.ArrayList;
551	import java.util.Comparator;
552	import java.util.LinkedHashSet;
553	import java.util.List;
554	import java.util.Locale;
555	import java.util.Set;
556	
557	/** A person on a sheet. */
558	@Entity
559	@Table(name = "person")
560	public class Person {
561	
562	    @Id
563	    @GeneratedValue(strategy = GenerationType.IDENTITY)
564	    private Long id;
565	
566	    @Column(name = "sheet_id", nullable = false)
567	    private String sheetId;
568	
569	    @Column(name = "name", nullable = false)
570	    private String name;
571	
572	    /** The name as uniqueness compares it: trimmed and lower-cased. */
573	    @Column(name = "name_key", nullable = false)
574	    private String nameKey;
575	
576	    /** Every grade the person was given, each from its from-date; the first from the beginning of time. */
577	    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
578	    @JoinColumn(name = "person_id", nullable = false)
579	    private List<PersonGrade> grades = new ArrayList<>();
580	
581	    /** The date the person is retired from; null while they are not retired. */
582	    @Column(name = "retired_from")
583	    private LocalDate retiredFrom;
584	
585	    /** The sheet's today when the person was last retired; null when never, or before this was kept. */
586	    @Column(name = "retired_made_on")
587	    private LocalDate retiredMadeOn;
588	
589	    /** The sheet's today when the person was added; null when added before this was kept. */
590	    @Column(name = "added_on")
591	    private LocalDate addedOn;
592	
593	    /** Every hold put on the person; their open claims dated within one, unless bound by a statement,
594	     *  count in no live total. */
595	    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
596	    @JoinColumn(name = "person_id", nullable = false)
597	    private Set<PersonHold> holds = new LinkedHashSet<>();
598	
599	    /** The person's own terms, in days; null when they have none and use their grade's, else the sheet's. */
600	    @Column(name = "terms")
601	    private Integer terms;
602	
603	    /** The person's contact, trimmed and lower-cased; null when they have none. */
604	    @Column(name = "contact")
605	    private String contact;
606	
607	    /** Bumped on each save; an edit made from an older version is refused. */
608	    @Version
609	    @Column(name = "version", nullable = false)
610	    private long version;
611	
612	    protected Person() {
613	    }
614	
615	    /** A person added to the sheet while its today is the date given (addedOn). */
616	    public Person(String sheetId, String name, Grade grade, LocalDate addedOn) {
617	        this.sheetId = sheetId;
618	        this.addedOn = addedOn;
619	        setName(name);
620	        grades.add(new PersonGrade(grade, null, addedOn));
621	    }
622	
623	    public LocalDate getAddedOn() {
624	        return addedOn;
625	    }
626	
627	    public Long getId() {
628	        return id;
629	    }
630	
631	    public String getSheetId() {
632	        return sheetId;
633	    }
634	
635	    public String getName() {
636	        return name;
637	    }
638	
639	    /** Stores the name with its surrounding spaces removed. */
640	    public void setName(String name) {
641	        this.name = name.trim();
642	        this.nameKey = keyOf(name);
643	    }
644	
645	    /** The key a name is compared on for uniqueness: without surrounding spaces or regard to case. */
646	    public static String keyOf(String name) {
647	        return name.trim().toLowerCase(Locale.ROOT);
648	    }
649	
650	    /** The grades the person was given, the one from the beginning of time first, then by from-date. */
651	    public List<PersonGrade> getGrades() {
652	        List<PersonGrade> ordered = new ArrayList<>(grades);
653	        ordered.sort((a, b) -> a.startsAfter(b) ? 1 : b.startsAfter(a) ? -1 : 0);
654	        return ordered;
655	    }
656	
657	    /** The grade in force on a date: the one with the latest from-date on or before it. */
658	    public Grade gradeOn(LocalDate date) {
659	        return gradeOn(date, null);
660	    }
661	
662	    /** The grade in force on a date as the person's grades stood at the end of another date (asOf; null:
663	     *  as they stand now): only the grades given while the sheet's today was on or before it count. */
664	    public Grade gradeOn(LocalDate date, LocalDate asOf) {
665	        PersonGrade inForce = null;
666	        for (PersonGrade g : grades) {
667	            if (asOf != null && !g.madeBy(asOf)) continue;
668	            if (g.appliesBy(date) && (inForce == null || g.startsAfter(inForce))) inForce = g;
669	        }
670	        return inForce == null ? null : inForce.getGrade();
671	    }
672	
673	    /** Give the person a grade from a date, replacing the grade they had from that same date and
674	     *  keeping every other one. */
675	    public void setGrade(Grade grade, LocalDate from, LocalDate madeOn) {
676	        for (PersonGrade g : grades) {
677	            if (from.equals(g.getFrom())) {
678	                if (g.getGrade() != grade) g.setGrade(grade, madeOn);
679	                return;
680	            }
681	        }
682	        grades.add(new PersonGrade(grade, from, madeOn));
683	    }
684	
685	    public LocalDate getRetiredFrom() {
686	        return retiredFrom;
687	    }
688	
689	    /** Retire the person from a date, while the sheet's today is the date given (madeOn). */
690	    public void setRetiredFrom(LocalDate retiredFrom, LocalDate madeOn) {
691	        this.retiredFrom = retiredFrom;
692	        this.retiredMadeOn = madeOn;
693	    }
694	
695	    /** Whether the person is retired: true as soon as a retirement date is set, whatever the date. */
696	    public boolean isRetired() {
697	        return retiredFrom != null;
698	    }
699	
700	    /** Whether a claim of this date is refused: one dated after the person's retirement date. */
701	    public boolean isRetiredOn(LocalDate date) {
702	        return retiredFrom != null && date.isAfter(retiredFrom);
703	    }
704	
705	    /** The holds put on the person, the one from the beginning of time first, then by from-date, then
706	     *  in the order they were put on. */
707	    public List<PersonHold> getHolds() {
708	        List<PersonHold> ordered = new ArrayList<>(holds);
709	        ordered.sort(Comparator.comparing(PersonHold::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()))
710	                .thenComparing(PersonHold::getId, Comparator.nullsLast(Comparator.naturalOrder())));
711	        return ordered;
712	    }
713	
714	    /** Whether the person has any hold, whatever its dates. */
715	    public boolean isHeld() {
716	        return !holds.isEmpty();
717	    }
718	
719	    /** Whether a date falls within one of the person's holds. */
720	    public boolean isHeldOn(LocalDate date) {
721	        return holds.stream().anyMatch(h -> h.covers(date));
722	    }
723	
724	    /** Whether the person's retirement date is reached by the sheet's today (on or after it). */
725	    public boolean isRetiredBy(LocalDate today) {
726	        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
727	    }
728	
729	    /** Whether the person's unbound open claim of this date leaves the live totals: dated within one of
730	     *  their holds, or the person's retirement date is reached by the sheet's today. */
731	    public boolean isLeftOut(LocalDate date, LocalDate today) {
732	        return isHeldOn(date) || isRetiredBy(today);
733	    }
734	
735	    /** Whether the person's unbound open claim of this date left the totals at the end of another date
736	     *  (asOf), which stands in for the sheet's today: dated within one of the holds put on them while the
737	     *  sheet's today was on or before it, or their retirement then made reached by it. */
738	    public boolean isLeftOutAsOf(LocalDate date, LocalDate asOf) {
739	        boolean held = holds.stream().anyMatch(h -> h.madeBy(asOf) && h.covers(date));
740	        boolean retired = retiredFrom != null && (retiredMadeOn == null || !retiredMadeOn.isAfter(asOf))
741	                && !asOf.isBefore(retiredFrom);
742	        return held || retired;
743	    }
744	
745	    /** Put a hold on the person from a date to a date (none: no end), while the sheet's today is the date
746	     *  given (madeOn). */
747	    public void hold(LocalDate from, LocalDate to, LocalDate madeOn) {
748	        holds.add(new PersonHold(from, to, madeOn));
749	    }
750	
751	    public Integer getTerms() {
752	        return terms;
753	    }
754	
755	    public void setTerms(Integer terms) {
756	        this.terms = terms;
757	    }
758	
759	    public String getContact() {
760	        return contact;
761	    }
762	
763	    /** Stores the contact trimmed and lower-cased; a blank contact is none. */
764	    public void setContact(String contact) {
765	        this.contact = contactOf(contact);
766	    }
767	
768	    /** A contact as stored: without surrounding spaces, lower-cased; null when blank or none. */
769	    public static String contactOf(String contact) {
770	        return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(Locale.ROOT);
771	    }
772	
773	    public long getVersion() {
774	        return version;
775	    }
776	}
