package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /** What the screen shows of a claim; the amount always has two decimals. The settled due is the
     *  due fixed when the claim was settled, or null when its due is live. Opened by is who opened
     *  the claim, or null when it was never opened. Stated is whether the person's last statement bound
     *  the claim; stated due is the figure it bound it to, or null when unbound or n/a then. Corrects is
     *  the number of the claim a correction corrects, or null when the claim is not a correction. The log is
     *  its status log, oldest first. Deferred until is the date the claim was last deferred until, or null when
     *  it never was; it is deferred while it is OPEN and the sheet's today is before that date. Proofs is
     *  the claim's proofs count. Split from is the number of the claim it was split off from, or null.
     *  Reminded is the last day a reminder was written for the claim, or null when it never was. Ref is its
     *  external reference, or null when it has none. Tags are its tags, sorted; empty when it has none.
     *  Void reason is the reason it was voided with, or null. Comments are its comments, oldest first.
     *  Edited by is who last edited it, or null when it never was. Settle batch is the number of the bulk
     *  settle batch that settled it, or null when it was settled one at a time or never. */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue,
            String openedBy, boolean stated, String statedDue, String corrects, LocalDate dueBy,
            List<LogLineView> log, LocalDate deferredUntil, int proofs, String splitFrom,
            boolean lateEntry, LocalDate reminded, String ref, List<String> tags, String voidReason,
            List<CommentView> comments, String editedBy, Integer settleBatch) {
        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getDueBy(), claim.getLog().stream().map(LogLineView::of).toList(),
                    claim.getDeferredUntil(), claim.getProofs(), claim.getSplitFrom(),
                    claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(),
                    claim.getTags(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentView::of).toList(), claim.getEditedBy(),
                    claim.getSettleBatch());
        }
    }

    /** A line of a claim's status log; the due has two decimals, or is null when it was n/a. */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {
        public static LogLineView of(ClaimLogLine line) {
            return new LogLineView(line.getStatus(), line.getBy(), line.getOn(),
                    line.getDue() == null ? null : line.getDue().toPlainString());
        }
    }

    /** A comment on a claim: who wrote it, the sheet's today then, and its text. */
    public record CommentView(String by, LocalDate on, String text) {
        public static CommentView of(ClaimComment comment) {
            return new CommentView(comment.getBy(), comment.getOn(), comment.getText());
        }
    }

    /** A claim's fields, as entered on the form; no date means the sheet's today. A negative amount
     *  is a correction, which names the number of the settled claim it corrects. */
    public record ClaimForm(
            @NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 220) String corrects,
            @Size(max = 220) String ref,
            @Size(max = 1000) String tags) {
    }

    /** The number a form's correction names, trimmed; none when blank. */
    private static String correctsOf(ClaimForm form) {
        return form.corrects() == null || form.corrects().isBlank() ? null : form.corrects().trim();
    }

    /** The claims selected to open or settle together. */
    public record BulkOpenForm(@NotNull @Size(max = 1000) List<@NotNull Long> ids) {
    }

    /** What a bulk open did: the claims it opened, and how many were opened and refused. */
    public record BulkOpenView(int opened, int refused, List<ClaimView> claims) {
    }

    /** What a bulk settle did: the claims it settled (or left pending), how many were settled and refused,
     *  and the number of the batch it made, or null when it settled none. */
    public record BulkSettleView(int settled, int refused, List<ClaimView> claims, Integer batch) {
    }

    /** The claims selected to move together, and the person they move to. */
    public record BulkReassignForm(@NotNull @Size(max = 1000) List<@NotNull Long> ids, @NotNull Long personId) {
    }

    /** What a bulk reassign did: the claims it moved, and how many were moved and refused. */
    public record BulkReassignView(int reassigned, int refused, List<ClaimView> claims) {
    }

    private final ClaimService service;
    private final BulkChangeService bulk;

    public ClaimController(ClaimService service, BulkChangeService bulk) {
        this.service = service;
        this.bulk = bulk;
    }

    /** The sheet's claims, newest first. */
    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(ClaimView::of).toList();
    }

    /** Every tag ever used on the sheet, by name. */
    @GetMapping("/tags")
    public List<String> tags(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.tags(sheetId.trim());
    }

    /** Add a claim to a person. */
    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid ClaimForm form) {
        return ClaimView.of(service.add(sheetId.trim(), SignedInUser.name(user), personId,
                form.amount(), form.date(), form.note(), correctsOf(form), form.ref(), form.tags()));
    }

    /** Edit a claim. */
    @PutMapping("/claims/{id}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid ClaimForm form) {
        return ClaimView.of(service.update(sheetId.trim(), SignedInUser.name(user), id,
                form.amount(), form.date(), form.note(), correctsOf(form), form.ref(), form.tags()));
    }

    /** Open a claim's editor, locking the claim for other users. */
    @PostMapping("/claims/{id}/lock")
    public ClaimView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.lock(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Cancel a claim's editor, releasing the user's lock on it. */
    @PostMapping("/claims/{id}/unlock")
    public ClaimView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.unlock(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Open a draft claim. */
    @PostMapping("/claims/{id}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), SignedInUser.name(user), id, ClaimStatus.OPEN));
    }

    /** Open the selected claims together in list order; each that cannot be opened is left as it is. */
    @PostMapping("/claims/open")
    public BulkOpenView openSelected(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkOpenForm form) {
        BulkChangeService.Result result = bulk.open(sheetId.trim(), SignedInUser.name(user), form.ids());
        return new BulkOpenView(result.changed().size(), result.refused(),
                result.changed().stream().map(ClaimView::of).toList());
    }

    /** Settle the selected claims together in list order; one left pending counts as settled, each
     *  that cannot be settled is left as it is. */
    @PostMapping("/claims/settle")
    public BulkSettleView settleSelected(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkOpenForm form) {
        BulkChangeService.SettleResult result = bulk.settle(sheetId.trim(), SignedInUser.name(user), form.ids());
        return new BulkSettleView(result.changed().size(), result.refused(),
                result.changed().stream().map(ClaimView::of).toList(), result.batch());
    }

    /** Move the selected claims to another person together in list order; each that cannot be moved
     *  is left as it is. */
    @PostMapping("/claims/reassign")
    public BulkReassignView reassignSelected(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkReassignForm form) {
        BulkChangeService.Result result = bulk.reassign(sheetId.trim(), SignedInUser.name(user), form.ids(),
                form.personId());
        return new BulkReassignView(result.changed().size(), result.refused(),
                result.changed().stream().map(ClaimView::of).toList());
    }

    /** Settle an open claim; a clerk's settling above the clerk limit leaves it pending. */
    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), SignedInUser.name(user), id, ClaimStatus.SETTLED));
    }

    /** Why a steward rejects a pending claim. */
    public record RejectForm(@NotBlank @Size(max = 200) String reason) {
    }

    /** Approve a pending claim, settling it. */
    @PostMapping("/claims/{id}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.approve(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Reject a pending claim for a reason, opening it again. */
    @PostMapping("/claims/{id}/reject")
    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid RejectForm form) {
        return ClaimView.of(service.reject(sheetId.trim(), SignedInUser.name(user), id, form.reason().trim()));
    }

    /** Re-settle a settled claim at what it would be due today as an open, unbound claim; a steward's change. */
    @PostMapping("/claims/{id}/resettle")
    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.resettle(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** The date a claim is deferred until. */
    public record DeferForm(@NotNull LocalDate until) {
    }

    /** Defer an open claim until a date after the sheet's today. */
    @PostMapping("/claims/{id}/defer")
    public ClaimView defer(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid DeferForm form) {
        return ClaimView.of(service.defer(sheetId.trim(), SignedInUser.name(user), id, form.until()));
    }

    /** Raise a claim's proofs count by one; refused for a settled or voided claim. */
    @PostMapping("/claims/{id}/proof")
    public ClaimView addProof(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.addProof(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Remind an open or pending claim, once per sheet's today. */
    @PostMapping("/claims/{id}/remind")
    public ClaimView remind(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.remind(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** The new date of a claim. */
    public record RedateForm(@NotNull LocalDate date) {
    }

    /** Re-date an open or pending claim; only a steward may. */
    @PostMapping("/claims/{id}/redate")
    public ClaimView redate(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid RedateForm form) {
        return ClaimView.of(service.redate(sheetId.trim(), SignedInUser.name(user), id, form.date()));
    }

    /** The amount split off a claim. */
    public record SplitForm(@NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount) {
    }

    /** What a split did: the claim split, with the rest of its amount, and the new claim split off it. */
    public record SplitView(ClaimView original, ClaimView split) {
    }

    /** Split an amount off an open claim into a new open claim. */
    @PostMapping("/claims/{id}/split")
    @ResponseStatus(HttpStatus.CREATED)
    public SplitView split(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid SplitForm form) {
        ClaimService.Split split = service.split(sheetId.trim(), SignedInUser.name(user), id, form.amount());
        return new SplitView(ClaimView.of(split.original()), ClaimView.of(split.split()));
    }

    /** The person a claim is moved to. */
    public record ReassignForm(@NotNull Long personId) {
    }

    /** Move a draft, open or pending claim to another person, as their newest claim; a steward's change. */
    @PostMapping("/claims/{id}/reassign")
    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid ReassignForm form) {
        return ClaimView.of(service.reassign(sheetId.trim(), SignedInUser.name(user), id, form.personId()));
    }

    /** The reason a claim is voided with, chosen from the sheet's list; none while the list is empty. */
    public record VoidForm(@Size(max = 100) String reason) {
    }

    /** Void a draft or open (or pending) claim, or, as a steward, a settled one within 7 days of its settlement;
     *  while the sheet has void reasons, with one of them. */
    @PostMapping("/claims/{id}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody(required = false) @Valid VoidForm form) {
        return ClaimView.of(service.voidClaim(sheetId.trim(), SignedInUser.name(user), id,
                form == null ? null : form.reason()));
    }

    /** The text of a comment on a claim. */
    public record CommentForm(@NotBlank @Size(max = 1000) String text) {
    }

    /** Comment a claim; an empty comment is refused. */
    @PostMapping("/claims/{id}/comments")
    public ClaimView comment(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid CommentForm form) {
        return ClaimView.of(service.comment(sheetId.trim(), SignedInUser.name(user), id, form.text()));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSettings;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.setting.SheetSettingDatedRepository;
import net.officefloor.hq.app.setting.SheetSettingRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total (late charges
 * included, held to the sheet's cap) and overdue-total (what is owed on their counting claims that are
 * open past their due-by, late charges included, skipping n/a), and the sheet's
 * claimed-total, due-total and overdue-total (the last two leaving out the single highest and lowest
 * person's figure when three or more people have one). A change takes a snapshot before it alters anything, then
 * {@link #recordChanges} audits, after the change's own lines, each person whose figures moved (in the
 * order they were added) and then the sheet's totals when they moved.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    /** A person's figures; a null due-total is n/a. */
    record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal)
                    && same(overdueTotal, other.overdueTotal);
        }
    }

    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(String sheetId, Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final SheetSettingDatedRepository dated;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SheetSettingRepository settings, SheetSettingDatedRepository dated, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.dated = dated;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now, within the caller's transaction. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        // The floor and late percent are those in force on each claim's date; the cap that in force today.
        DatedSettings values = DatedSettings.of(dated, sheetId);
        BigDecimal cap = values.capOn(today);
        LocalDate policyDate = Rounding.policyDate(SettingService.policyDateOf(settings, sheetId), today);
        Map<Grade, List<Rate>> ratesByGrade = new LinkedHashMap<>();
        for (Rate rate : rates.findBySheetIdInOrder(sheetId)) {
            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        }
        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            claimsByPerson.computeIfAbsent(claim.getPersonId(), p -> new ArrayList<>()).add(claim);
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            Grade gradeToday = today == null ? null : person.gradeOn(today);
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean keptFigure = false;
            List<Claim> theirs = claimsByPerson.getOrDefault(person.getId(), List.of());
            for (Claim claim : theirs) {
                if (!counts(person, claim, today)) continue;
                claimed = claimed.add(claim.getAmount());
                // A claim's live figure is at the grade in force on its date.
                Grade grade = person.gradeOn(claim.getDate());
                RoundingMode rounding = Rounding.of(Rounding.dateOf(claim, corrected(claim, theirs)), policyDate);
                BigDecimal figure = figure(claim, ratesByGrade.getOrDefault(grade, List.of()), rounding);
                int grace = values.graceOn(grade, claim.getDate());
                BigDecimal owed = LateCharge.dueOf(claim, figure, values.floorOn(claim.getDate()), today,
                        grace, values::latePctOn, rounding);
                if (owed != null) due = due.add(owed);
                if (owed != null && isOverdue(claim, grace, today)) overdue = overdue.add(owed);
                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) {
                    keptFigure = true;
                }
                // A live figure at a grade other than today's is not undone by today's grade having no rate.
                if (figure != null && grade != gradeToday) keptFigure = true;
                // Nor is a live figure on a claim dated by today undone by its rate having ended since.
                if (figure != null && today != null && !claim.getDate().isAfter(today)) keptFigure = true;
            }
            // n/a when no rate of the grade in force today is in force today and no claim keeps a figure.
            // Held to the sheet's cap; n/a is not capped.
            BigDecimal personDue = SettingService.capped((today == null
                    || Rate.inForce(ratesByGrade.getOrDefault(gradeToday, List.of()), today) == null) && !keptFigure
                            ? null : due, cap);
            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (personDue != null) dues.add(personDue);
            overdues.add(overdue);
        }
        return new Snapshot(sheetId, figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
    }

    /** Audit, once the transaction commits, each person's due-total as it stood in the snapshot, in the
     *  order they were added. */
    public void recordSnapshot(String user, Snapshot before) {
        String prefix = " sheet=" + before.sheetId() + " by=" + user;
        before.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT" + prefix + " name="
                + figures.name() + " due-total=" + text(figures.dueTotal())));
    }

    /** Audit, once the transaction commits, the figures that moved since the snapshot was taken. */
    public void recordChanges(String user, Snapshot before) {
        Snapshot after = snapshot(before.sheetId());
        String prefix = " sheet=" + before.sheetId() + " by=" + user;
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + text(now.claimed())
                        + " due-total=" + text(now.dueTotal()) + " overdue-total=" + text(now.overdueTotal()));
            }
        });
        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
                || !same(before.overdueTotal(), after.overdueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + text(after.claimedTotal())
                    + " due-total=" + text(after.dueTotal()) + " overdue-total=" + text(after.overdueTotal()));
        }
    }

    /** Whether the claim is overdue: open and not deferred, with its due-by plus the grace days of its
     *  person's grade before the sheet's today. */
    private static boolean isOverdue(Claim claim, int grace, LocalDate today) {
        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null
                && LateCharge.lateFrom(claim, grace).isBefore(today);
    }

    /** Only open (PENDING included) and settled claims count toward what is claimed and due; a person's
     *  open claims dated within one of their holds, or all of them once their retirement date is reached,
     *  do not, unless a statement binds them; nor does a
     *  claim deferred on the sheet's today. */
    private static boolean counts(Person person, Claim claim, LocalDate today) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
                        && (claim.isBound() || !person.isLeftOut(claim.getDate(), today)));
    }

    /** The claim's figure, as ClaimService.figure works it out: the settled due, else the stated due,
     *  (unless PENDING), else the rate figure at the grade's rate in force on its date, rounded as the claim rounds,
     *  before any late charge and floor; null when that is n/a. */
    private static BigDecimal figure(Claim claim, List<Rate> gradeRates, RoundingMode rounding) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isBound()) return claim.getStatedDue();
        Rate rate = Rate.inForce(gradeRates, claim.getDate());
        if (rate == null) return null;
        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, rounding);
    }

    /** Of the person's claims, the one a correction corrects by number; null for any other claim. */
    private static Claim corrected(Claim claim, List<Claim> theirs) {
        if (!claim.isCorrection() || claim.getCorrects() == null) return null;
        for (Claim other : theirs) {
            if (claim.getCorrects().equals(other.getNumber())) return other;
        }
        return null;
    }

    /** The sum of the figures, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal total = figures.stream().reduce(ZERO, BigDecimal::add);
        if (figures.size() < 3) return total;
        return total.subtract(figures.stream().max(BigDecimal::compareTo).get())
                .subtract(figures.stream().min(BigDecimal::compareTo).get());
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
    }

    private static String text(BigDecimal figure) {
        return figure == null ? "n/a" : figure.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/** A person on a sheet. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The name as uniqueness compares it: trimmed and lower-cased. */
    @Column(name = "name_key", nullable = false)
    private String nameKey;

    /** Every grade the person was given, each from its from-date; the first from the beginning of time. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private List<PersonGrade> grades = new ArrayList<>();

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The sheet's today when the person was last retired; null when never, or before this was kept. */
    @Column(name = "retired_made_on")
    private LocalDate retiredMadeOn;

    /** The sheet's today when the person was added; null when added before this was kept. */
    @Column(name = "added_on")
    private LocalDate addedOn;

    /** Every hold put on the person; their open claims dated within one, unless bound by a statement,
     *  count in no live total. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private Set<PersonHold> holds = new LinkedHashSet<>();

    /** The person's own terms, in days; null when they have none and use their grade's, else the sheet's. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** Bumped on each save; an edit made from an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    /** A person added to the sheet while its today is the date given (addedOn). */
    public Person(String sheetId, String name, Grade grade, LocalDate addedOn) {
        this.sheetId = sheetId;
        this.addedOn = addedOn;
        setName(name);
        grades.add(new PersonGrade(grade, null, addedOn));
    }

    public LocalDate getAddedOn() {
        return addedOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    /** Stores the name with its surrounding spaces removed. */
    public void setName(String name) {
        this.name = name.trim();
        this.nameKey = keyOf(name);
    }

    /** The key a name is compared on for uniqueness: without surrounding spaces or regard to case. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    /** The grades the person was given, the one from the beginning of time first, then by from-date. */
    public List<PersonGrade> getGrades() {
        List<PersonGrade> ordered = new ArrayList<>(grades);
        ordered.sort((a, b) -> a.startsAfter(b) ? 1 : b.startsAfter(a) ? -1 : 0);
        return ordered;
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public Grade gradeOn(LocalDate date) {
        return gradeOn(date, null);
    }

    /** The grade in force on a date as the person's grades stood at the end of another date (asOf; null:
     *  as they stand now): only the grades given while the sheet's today was on or before it count. */
    public Grade gradeOn(LocalDate date, LocalDate asOf) {
        PersonGrade inForce = null;
        for (PersonGrade g : grades) {
            if (asOf != null && !g.madeBy(asOf)) continue;
            if (g.appliesBy(date) && (inForce == null || g.startsAfter(inForce))) inForce = g;
        }
        return inForce == null ? null : inForce.getGrade();
    }

    /** Give the person a grade from a date, replacing the grade they had from that same date and
     *  keeping every other one. */
    public void setGrade(Grade grade, LocalDate from, LocalDate madeOn) {
        for (PersonGrade g : grades) {
            if (from.equals(g.getFrom())) {
                if (g.getGrade() != grade) g.setGrade(grade, madeOn);
                return;
            }
        }
        grades.add(new PersonGrade(grade, from, madeOn));
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    /** Retire the person from a date, while the sheet's today is the date given (madeOn). */
    public void setRetiredFrom(LocalDate retiredFrom, LocalDate madeOn) {
        this.retiredFrom = retiredFrom;
        this.retiredMadeOn = madeOn;
    }

    /** Whether the person is retired: true as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether a claim of this date is refused: one dated after the person's retirement date. */
    public boolean isRetiredOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }

    /** The holds put on the person, the one from the beginning of time first, then by from-date, then
     *  in the order they were put on. */
    public List<PersonHold> getHolds() {
        List<PersonHold> ordered = new ArrayList<>(holds);
        ordered.sort(Comparator.comparing(PersonHold::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()))
                .thenComparing(PersonHold::getId, Comparator.nullsLast(Comparator.naturalOrder())));
        return ordered;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether a date falls within one of the person's holds. */
    public boolean isHeldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Whether the person's retirement date is reached by the sheet's today (on or after it). */
    public boolean isRetiredBy(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /** Whether the person's unbound open claim of this date leaves the live totals: dated within one of
     *  their holds, or the person's retirement date is reached by the sheet's today. */
    public boolean isLeftOut(LocalDate date, LocalDate today) {
        return isHeldOn(date) || isRetiredBy(today);
    }

    /** Whether the person's unbound open claim of this date left the totals at the end of another date
     *  (asOf), which stands in for the sheet's today: dated within one of the holds put on them while the
     *  sheet's today was on or before it, or their retirement then made reached by it. */
    public boolean isLeftOutAsOf(LocalDate date, LocalDate asOf) {
        boolean held = holds.stream().anyMatch(h -> h.madeBy(asOf) && h.covers(date));
        boolean retired = retiredFrom != null && (retiredMadeOn == null || !retiredMadeOn.isAfter(asOf))
                && !asOf.isBefore(retiredFrom);
        return held || retired;
    }

    /** Put a hold on the person from a date to a date (none: no end), while the sheet's today is the date
     *  given (madeOn). */
    public void hold(LocalDate from, LocalDate to, LocalDate madeOn) {
        holds.add(new PersonHold(from, to, madeOn));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public String getContact() {
        return contact;
    }

    /** Stores the contact trimmed and lower-cased; a blank contact is none. */
    public void setContact(String contact) {
        this.contact = contactOf(contact);
    }

    /** A contact as stored: without surrounding spaces, lower-cased; null when blank or none. */
    public static String contactOf(String contact) {
        return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(Locale.ROOT);
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A hold on a person, from its from-date (or the beginning of time, when it has none) to its to-date
 *  (or for good, when it has none), both days included. */
@Entity
@Table(name = "person_hold")
public class PersonHold {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    /** The sheet's today when the hold was put on; null when put on before this was kept. */
    @Column(name = "made_on")
    private LocalDate madeOn;

    protected PersonHold() {
    }

    PersonHold(LocalDate from, LocalDate to, LocalDate madeOn) {
        this.from = from;
        this.to = to;
        this.madeOn = madeOn;
    }

    /** Whether the hold was put on while the sheet's today was on or before the date. */
    boolean madeBy(LocalDate date) {
        return madeOn == null || !madeOn.isAfter(date);
    }

    Long getId() {
        return id;
    }

    /** The date the hold starts, or null when it holds from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** The date the hold ends, or null when it has no end. */
    public LocalDate getTo() {
        return to;
    }

    /** Whether the date falls within the hold. */
    boolean covers(LocalDate date) {
        return (from == null || !date.isBefore(from)) && (to == null || !date.isAfter(to));
    }
}
