package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PersonService {

    private final PersonRepository people;
    private final PersonPatronRepository patrons;
    private final PersonWatchRepository watches;
    private final SheetService sheets;
    private final Rollup rollup;
    private final Audit audit;

    public PersonService(PersonRepository people, PersonPatronRepository patrons, PersonWatchRepository watches,
            SheetService sheets, Rollup rollup, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's people in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The ids of each person's patrons on the sheet, by person, in the order they were named; a person
     *  with no patrons is left out. */
    @Transactional(readOnly = true)
    public Map<Long, List<Long>> patronIds(String sheetId) {
        Map<Long, List<Long>> by = new LinkedHashMap<>();
        for (PersonPatron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
            by.computeIfAbsent(patron.getPersonId(), p -> new ArrayList<>()).add(patron.getPatronId());
        }
        return by;
    }

    /** The ids of the person's patrons, in the order they were named. */
    @Transactional(readOnly = true)
    public List<Long> patronIdsOf(long id) {
        return patrons.findByPersonIdOrderByIdAsc(id).stream().map(PersonPatron::getPatronId).toList();
    }

    /** Name another person on the sheet as one of the person's patrons; refused for the person
     *  themselves and for someone already their patron. */
    @Transactional
    public Person addPatron(String sheetId, String user, long id, long patronId) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw alreadyPatron();
        }
        try {
            patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException raced) {
            // Another user named the same patron at the same moment.
            throw alreadyPatron();
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " patron=" + patron.getName());
        return person;
    }

    /** The ids of the people on the sheet the user watches. */
    @Transactional(readOnly = true)
    public Set<Long> watchedIds(String sheetId, String user) {
        return watches.findBySheetIdAndUserName(sheetId, user).stream().map(PersonWatch::getPersonId)
                .collect(Collectors.toSet());
    }

    /** Whether the user watches the person. */
    @Transactional(readOnly = true)
    public boolean isWatched(long id, String user) {
        return watches.existsByPersonIdAndUserName(id, user);
    }

    /** Start (true) or stop (false) the user watching the person; when the user already does as asked,
     *  nothing changes. A user who starts watching again is told after those watching meanwhile. */
    @Transactional
    public Person watch(String sheetId, String user, long id, boolean on) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Optional<PersonWatch> watching = watches.findByPersonIdAndUserName(person.getId(), user);
        if (on == watching.isPresent()) return person;
        if (on) {
            try {
                watches.saveAndFlush(new PersonWatch(sheetId, person.getId(), user));
            } catch (DataIntegrityViolationException raced) {
                // The same user started watching from another screen at the same moment.
                throw new ResponseStatusException(HttpStatus.CONFLICT, "You already watch this person.");
            }
        } else {
            watches.delete(watching.get());
            watches.flush();
        }
        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName());
        return person;
    }

    private static ResponseStatusException alreadyPatron() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
    }

    /** Add a person to the sheet. */
    @Transactional
    public Person add(String sheetId, String user, String name, Grade grade, Integer terms) {
        return add(sheetId, user, name, grade, terms, null);
    }

    /** Add a person to the sheet with a contact (blank or null: none); refused when another person on
     *  the sheet has the same contact. */
    @Transactional
    public Person add(String sheetId, String user, String name, Grade grade, Integer terms, String contact) {
        sheets.load(sheetId);
        if (people.existsBySheetIdAndNameKey(sheetId, Person.keyOf(name))) {
            throw nameInUse();
        }
        String contactKey = Person.contactOf(contact);
        if (contactKey != null && people.existsBySheetIdAndContact(sheetId, contactKey)) {
            throw contactInUse();
        }
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        Person fresh = new Person(sheetId, name, grade, sheets.today(sheetId));
        fresh.setTerms(terms);
        fresh.setContact(contactKey);
        Person person = save(fresh);
        recordChange("PERSON_ADDED", user, person, (terms == null ? "" : " terms=" + terms)
                + (contactKey == null ? "" : " contact=" + contactKey));
        rollup.recordChanges(user, before);
        return person;
    }

    /** Change a person's name and give them a grade from a from-date (none: the sheet's today), keeping
     *  the grades they were given from other dates; refused when someone has saved the person since
     *  the editor loaded this version of them, or when another person on the sheet has the contact
     *  given (blank or null: none). */
    @Transactional
    public Person update(String sheetId, String user, long id, long version, String name, Grade grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (person.getVersion() != version) {
            throw changedMeanwhile();
        }
        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.keyOf(name), id)) {
            throw nameInUse();
        }
        String contactKey = Person.contactOf(contact);
        if (contactKey != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contactKey, id)) {
            throw contactInUse();
        }
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        boolean contactChanged = !Objects.equals(person.getContact(), contactKey);
        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
        person.setName(name);
        person.setGrade(grade, gradeFrom != null ? gradeFrom : sheets.today(sheetId), sheets.today(sheetId));
        person.setTerms(terms);
        person.setContact(contactKey);
        Person saved = save(person);
        recordChange("PERSON_EDITED", user, saved, (termsChanged ? " terms=" + (terms == null ? "" : terms) : "")
                + (contactChanged ? " contact=" + (contactKey == null ? "" : contactKey) : ""));
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Retire a person from a date, the sheet's today when none is given. Once the sheet's today reaches
     *  the date, their open claims count in no live total, unless a statement binds them; their settled
     *  claims still count. Claims dated after the date can no longer be added to them. */
    @Transactional
    public Person retire(String sheetId, String user, long id, LocalDate from) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        LocalDate dated = from != null ? from : sheets.today(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        person.setRetiredFrom(dated, sheets.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + dated);
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Put a hold on a person from a date (none: the sheet's today) to a date (none: no end); refused
     *  when it ends before it starts. Their open claims dated within it count in no live total, unless
     *  a statement binds them; their settled claims still count. */
    @Transactional
    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        LocalDate dated = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(dated)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
        }
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        person.hold(dated, to, sheets.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " from=" + dated);
        rollup.recordChanges(user, before);
        return saved;
    }

    /** The person's audit line, with the grade in force on the sheet's today, then the fields given. */
    private void recordChange(String event, String user, Person person, String fields) {
        audit.recordOnCommit(event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(sheets.today(person.getSheetId()))
                + fields);
    }

    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (OptimisticLockingFailureException raced) {
            // Another user saved the same person at the same moment.
            throw changedMeanwhile();
        } catch (DataIntegrityViolationException raced) {
            // Another user took the same name, or the same contact, at the same moment.
            String cause = String.valueOf(raced.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
            throw cause.contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
        }
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved this person since it was opened.");
    }

    private static ResponseStatusException contactInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on the sheet.");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on the sheet.");
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** A grade the person was given, from its from-date (null: from the beginning of time). */
    public record GradeView(Grade grade, LocalDate from) {
    }

    /** A hold put on the person, from its from-date (null: the beginning of time) to its to-date (null: no end). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** What the screen shows of a person: grade is the one in force on the sheet's today, grades every
     *  grade they were given, the one from the beginning of time first, then by from-date; held whether
     *  they have any hold, holds every hold put on them, by from-date; watched whether the signed-in
     *  user watches them. */
    public record PersonView(long id, String name, Grade grade, List<GradeView> grades, long version,
            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds,
            List<Long> patronIds, boolean watched, Integer terms, String contact) {
        /** A person with no patrons, with the grade in force on the sheet's today. */
        public static PersonView of(Person person, LocalDate today, boolean watched) {
            return of(person, List.of(), today, watched);
        }

        /** A person with the ids of their patrons, in the order they were named, the grade in force
         *  on the sheet's today, and whether the signed-in user watches them. */
        public static PersonView of(Person person, List<Long> patronIds, LocalDate today, boolean watched) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFrom())).toList(),
                    person.getVersion(), person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFrom(), h.getTo())).toList(), patronIds,
                    watched, person.getTerms(), person.getContact());
        }
    }

    /** A person's own terms as entered: whole days, blank for none. */
    static final String TERMS = "\\s*\\d{0,5}\\s*";

    /** A person's fields, as entered on the form; a new person's grade applies from the beginning of time,
     *  their terms are whole days, blank for none; a blank contact is none. */
    public record PersonForm(@NotBlank @Size(max = 200) String name, @NotNull Grade grade,
            @Pattern(regexp = TERMS) String terms, @Size(max = 200) String contact) {
    }

    /** A person's fields as edited, with the version of the person the editor loaded; the grade is
     *  given from the from-date, none meaning the sheet's today. */
    public record PersonEdit(@NotBlank @Size(max = 200) String name, @NotNull Grade grade, LocalDate gradeFrom,
            @Pattern(regexp = TERMS) String terms, @Size(max = 200) String contact, @NotNull Long version) {
    }

    /** The person named as a patron. */
    public record PatronForm(@NotNull Long patronId) {
    }

    /** Whether the signed-in user is to watch the person. */
    public record WatchForm(@NotNull Boolean on) {
    }

    /** A retirement; no date means the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    /** A hold; no from-date means the sheet's today, no to-date no end. */
    public record HoldForm(LocalDate from, LocalDate to) {
    }

    /** The people selected to be given a grade together, from the from-date (none: the sheet's today). */
    public record BulkGradeForm(@NotNull List<@NotNull Long> ids, @NotNull Grade grade, LocalDate from) {
    }

    /** What a bulk grade did: the people it changed, and how many. */
    public record BulkGradeView(List<PersonView> people, int changed) {
    }

    private final PersonService service;
    private final BulkGradeService bulkGrade;
    private final SheetService sheets;

    public PersonController(PersonService service, BulkGradeService bulkGrade, SheetService sheets) {
        this.service = service;
        this.bulkGrade = bulkGrade;
        this.sheets = sheets;
    }

    /** The sheet's people in the order they were added. */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(name = SignedInUser.HEADER, required = false) String user) {
        String sheet = sheetId.trim();
        Map<Long, List<Long>> patronIds = service.patronIds(sheet);
        Set<Long> watched = user == null || user.isBlank() ? Set.of()
                : service.watchedIds(sheet, SignedInUser.name(user));
        LocalDate today = sheets.today(sheet);
        return service.list(sheet).stream()
                .map(p -> PersonView.of(p, patronIds.getOrDefault(p.getId(), List.of()), today,
                        watched.contains(p.getId())))
                .toList();
    }

    /** Add a person. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PersonForm form) {
        Person added = service.add(sheetId.trim(), SignedInUser.name(user), form.name(), form.grade(),
                termsOf(form.terms()), form.contact());
        return PersonView.of(added, sheets.today(added.getSheetId()), false);
    }

    /** Edit a person. */
    @PutMapping("/{id}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PersonEdit form) {
        return view(service.update(sheetId.trim(), SignedInUser.name(user), id, form.version(),
                form.name(), form.grade(), form.gradeFrom(), termsOf(form.terms()), form.contact()), user);
    }

    /** Give the selected people a grade together, each in list order as the person form would. */
    @PostMapping("/grade")
    public BulkGradeView grade(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkGradeForm form) {
        List<Person> changed = bulkGrade.grade(sheetId.trim(), SignedInUser.name(user), form.ids(), form.grade(),
                form.from());
        return new BulkGradeView(changed.stream().map(p -> view(p, user)).toList(), changed.size());
    }

    /** Retire a person from a date. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody RetireForm form) {
        return view(service.retire(sheetId.trim(), SignedInUser.name(user), id, form.from()), user);
    }

    /** Put a hold on a person. */
    @PostMapping("/{id}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody HoldForm form) {
        return view(service.hold(sheetId.trim(), SignedInUser.name(user), id, form.from(), form.to()), user);
    }

    /** Name another person on the sheet as one of the person's patrons. */
    @PostMapping("/{id}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PatronForm form) {
        return view(service.addPatron(sheetId.trim(), SignedInUser.name(user), id, form.patronId()), user);
    }

    /** Start or stop the signed-in user watching a person. */
    @PutMapping("/{id}/watch")
    public PersonView watch(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid WatchForm form) {
        return view(service.watch(sheetId.trim(), SignedInUser.name(user), id, form.on()), user);
    }

    /** The terms as entered, in days; null when left blank. */
    private static Integer termsOf(String terms) {
        return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
    }

    private PersonView view(Person person, String user) {
        return PersonView.of(person, service.patronIdsOf(person.getId()), sheets.today(person.getSheetId()),
                service.isWatched(person.getId(), SignedInUser.name(user)));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.Grade;

/**
 * A sheet's dated settings as the store held them when read: for each key, the values it takes from
 * their from-dates, in date order. The value in force on a date is the one of the latest from-date on or
 * before it; before every from-date, and from a blank value, a key has its starting value (the floor
 * {@link SettingService#DEFAULT_FLOOR}, the late percent {@link SettingService#DEFAULT_LATE_PCT}, the terms
 * {@link SettingService#DEFAULT_TERMS}; none for the clerk limit, the proof threshold, a grade's own proof threshold, the note threshold, the cap, a grade's own terms and a grade's grace days).
 */
public final class DatedSettings {

    private final Map<String, List<SheetSettingDated>> byKey;

    private DatedSettings(Map<String, List<SheetSettingDated>> byKey) {
        this.byKey = byKey;
    }

    /** The sheet's dated settings as the store holds them, within the caller's transaction. */
    public static DatedSettings of(SheetSettingDatedRepository settings, String sheetId) {
        return of(settings.findBySheetIdOrderByKeyAscFromAsc(sheetId));
    }

    /** Dated settings of the values given, in key then date order. */
    public static DatedSettings of(List<SheetSettingDated> settings) {
        Map<String, List<SheetSettingDated>> byKey = new LinkedHashMap<>();
        for (SheetSettingDated s : settings) byKey.computeIfAbsent(s.getKey(), k -> new ArrayList<>()).add(s);
        return new DatedSettings(byKey);
    }

    /** The key's values from their from-dates, in date order. */
    public List<SheetSettingDated> history(String key) {
        return byKey.getOrDefault(key, List.of());
    }

    /** The keys that have a value recorded. */
    public Iterable<String> keys() {
        return byKey.keySet();
    }

    /** The key's value in force on the date, or null when it has none then (blank or before every from-date). */
    public String on(String key, LocalDate date) {
        String value = null;
        if (date == null) return null;
        for (SheetSettingDated s : history(key)) {
            if (s.getFrom().isAfter(date)) break;
            value = s.getValue();
        }
        return value == null || value.isEmpty() ? null : value;
    }

    private BigDecimal decimalOn(String key, LocalDate date) {
        String value = on(key, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The floor in force on the date, with two decimals. */
    public BigDecimal floorOn(LocalDate date) {
        BigDecimal floor = decimalOn(SettingService.FLOOR, date);
        return floor == null ? SettingService.DEFAULT_FLOOR : floor;
    }

    /** The late percent in force on the date, with two decimals. */
    public BigDecimal latePctOn(LocalDate date) {
        BigDecimal pct = decimalOn(SettingService.LATE_PCT, date);
        return pct == null ? SettingService.DEFAULT_LATE_PCT : pct;
    }

    /** The cap in force on the date, or null when there is none. */
    public BigDecimal capOn(LocalDate date) {
        return decimalOn(SettingService.CAP, date);
    }

    /** The proof threshold in force on the date, or null when there is none. */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return decimalOn(SettingService.PROOF_THRESHOLD, date);
    }

    /** The proof threshold of a grade in force on the date: its own when set then, else the sheet's; null
     *  when there is none. */
    public BigDecimal proofThresholdOn(Grade grade, LocalDate date) {
        BigDecimal own = grade == null ? null : decimalOn(SettingService.proofThresholdKey(grade), date);
        return own != null ? own : proofThresholdOn(date);
    }

    /** The note threshold in force on the date, or null when there is none. */
    public BigDecimal noteThresholdOn(LocalDate date) {
        return decimalOn(SettingService.NOTE_THRESHOLD, date);
    }

    /** The clerk limit in force on the date, or null when there is none. */
    public BigDecimal clerkLimitOn(LocalDate date) {
        return decimalOn(SettingService.CLERK_LIMIT, date);
    }

    /** The sheet's terms in force on the date, in days. */
    public int termsOn(LocalDate date) {
        String value = on(SettingService.TERMS, date);
        return value == null ? SettingService.DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The grade's own terms in force on the date, in days, or null when it uses the sheet's then. */
    public Integer gradeTermsOn(Grade grade, LocalDate date) {
        String value = on(SettingService.termsKey(grade), date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The grade's grace days in force on the date, or 0 when it has none then (no grade has none). */
    public int graceOn(Grade grade, LocalDate date) {
        String value = grade == null ? null : on(SettingService.graceKey(grade), date);
        return value == null ? 0 : Integer.parseInt(value);
    }

    /** The terms of a grade in force on the date: its own, else the sheet's (no grade has the sheet's). */
    public int termsOn(Grade grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Grade;

/** One of the sheet's rates for a grade: a percent with two decimals, in force from its from-date
 *  (or from the beginning of time, when it has none) until the grade's next rate, and no later than
 *  its to-date when it has one. */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Enumerated(EnumType.STRING)
    @Column(name = "grade", nullable = false)
    private Grade grade;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    protected Rate() {
    }

    public Rate(String sheetId, Grade grade, LocalDate from, LocalDate to, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        setPct(pct);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Grade getGrade() {
        return grade;
    }

    /** The date the rate is in force from, or null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** The last date the rate is in force, or null when it runs until the grade's next rate. */
    public LocalDate getTo() {
        return to;
    }

