    /** Change a person's name and give them a grade from a from-date (none: the sheet's today), keeping
     *  the grades they were given from other dates; refused when someone has saved the person since
     *  the editor loaded this version of them, or when another person on the sheet has the contact
     *  given (blank or null: none). */
    @Transactional
    public Person update(String sheetId, String user, long id, long version, String name, Grade grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (person.getVersion() != version) {
            throw changedMeanwhile();
        }
        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.keyOf(name), id)) {
            throw nameInUse();
        }
        String contactKey = Person.contactOf(contact);
        if (contactKey != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contactKey, id)) {
            throw contactInUse();
        }
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        boolean contactChanged = !Objects.equals(person.getContact(), contactKey);
        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
        person.setName(name);
        person.setGrade(grade, gradeFrom != null ? gradeFrom : sheets.today(sheetId), sheets.today(sheetId));
        person.setTerms(terms);
        person.setContact(contactKey);
        Person saved = save(person);
        recordChange("PERSON_EDITED", user, saved, (termsChanged ? " terms=" + (terms == null ? "" : terms) : "")
                + (contactChanged ? " contact=" + (contactKey == null ? "" : contactKey) : ""));
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Retire a person from a date, the sheet's today when none is given. Once the sheet's today reaches
     *  the date, their open claims count in no live total, unless a statement binds them; their settled
     *  claims still count. Claims dated after the date can no longer be added to them. */
    @Transactional
    public Person retire(String sheetId, String user, long id, LocalDate from) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        LocalDate dated = from != null ? from : sheets.today(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        person.setRetiredFrom(dated, sheets.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + dated);
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Put a hold on a person from a date (none: the sheet's today) to a date (none: no end); refused
     *  when it ends before it starts. Their open claims dated within it count in no live total, unless
     *  a statement binds them; their settled claims still count. */
    @Transactional
    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        LocalDate dated = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(dated)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
        }
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        person.hold(dated, to, sheets.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " from=" + dated);
        rollup.recordChanges(user, before);
        return saved;
    }

    /** The person's audit line, with the grade in force on the sheet's today, then the fields given. */
    private void recordChange(String event, String user, Person person, String fields) {
        audit.recordOnCommit(event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(sheets.today(person.getSheetId()))
                + fields);
    }

    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (OptimisticLockingFailureException raced) {
            // Another user saved the same person at the same moment.
            throw changedMeanwhile();
        } catch (DataIntegrityViolationException raced) {
            // Another user took the same name, or the same contact, at the same moment.
            String cause = String.valueOf(raced.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
            throw cause.contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
        }
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved this person since it was opened.");
    }

    private static ResponseStatusException contactInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on the sheet.");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on the sheet.");
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** A grade the person was given, from its from-date (null: from the beginning of time). */
    public record GradeView(Grade grade, LocalDate from) {
    }

    /** A hold put on the person, from its from-date (null: the beginning of time) to its to-date (null: no end). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** What the screen shows of a person: grade is the one in force on the sheet's today, grades every
     *  grade they were given, the one from the beginning of time first, then by from-date; held whether
     *  they have any hold, holds every hold put on them, by from-date; watched whether the signed-in
     *  user watches them. */
    public record PersonView(long id, String name, Grade grade, List<GradeView> grades, long version,
            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds,
            List<Long> patronIds, boolean watched, Integer terms, String contact) {
        /** A person with no patrons, with the grade in force on the sheet's today. */
        public static PersonView of(Person person, LocalDate today, boolean watched) {
            return of(person, List.of(), today, watched);
        }

        /** A person with the ids of their patrons, in the order they were named, the grade in force
         *  on the sheet's today, and whether the signed-in user watches them. */
        public static PersonView of(Person person, List<Long> patronIds, LocalDate today, boolean watched) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFrom())).toList(),
                    person.getVersion(), person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFrom(), h.getTo())).toList(), patronIds,
                    watched, person.getTerms(), person.getContact());
        }
    }

    /** A person's own terms as entered: whole days, blank for none. */
    static final String TERMS = "\\s*\\d{0,5}\\s*";

    /** A person's fields, as entered on the form; a new person's grade applies from the beginning of time,
     *  their terms are whole days, blank for none; a blank contact is none. */
    public record PersonForm(@NotBlank @Size(max = 200) String name, @NotNull Grade grade,

    /** The key's value in force on the date, or null when it has none then (blank or before every from-date). */
    public String on(String key, LocalDate date) {
        String value = null;
        if (date == null) return null;
        for (SheetSettingDated s : history(key)) {
            if (s.getFrom().isAfter(date)) break;
            value = s.getValue();
        }
        return value == null || value.isEmpty() ? null : value;
    }

    private BigDecimal decimalOn(String key, LocalDate date) {
        String value = on(key, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The floor in force on the date, with two decimals. */
    public BigDecimal floorOn(LocalDate date) {
        BigDecimal floor = decimalOn(SettingService.FLOOR, date);
        return floor == null ? SettingService.DEFAULT_FLOOR : floor;
    }

    /** The late percent in force on the date, with two decimals. */
    public BigDecimal latePctOn(LocalDate date) {
        BigDecimal pct = decimalOn(SettingService.LATE_PCT, date);
        return pct == null ? SettingService.DEFAULT_LATE_PCT : pct;
    }

    /** The cap in force on the date, or null when there is none. */
    public BigDecimal capOn(LocalDate date) {
        return decimalOn(SettingService.CAP, date);
    }

    /** The proof threshold in force on the date, or null when there is none. */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return decimalOn(SettingService.PROOF_THRESHOLD, date);
    }

    /** The proof threshold of a grade in force on the date: its own when set then, else the sheet's; null
     *  when there is none. */
    public BigDecimal proofThresholdOn(Grade grade, LocalDate date) {
        BigDecimal own = grade == null ? null : decimalOn(SettingService.proofThresholdKey(grade), date);
        return own != null ? own : proofThresholdOn(date);
    }

    /** The note threshold in force on the date, or null when there is none. */
    public BigDecimal noteThresholdOn(LocalDate date) {
        return decimalOn(SettingService.NOTE_THRESHOLD, date);
    }

    /** The clerk limit in force on the date, or null when there is none. */
    public BigDecimal clerkLimitOn(LocalDate date) {
        return decimalOn(SettingService.CLERK_LIMIT, date);
    }

