/**
 * The history of each sheet, for the as-of view. Every commit of a change on a sheet keeps all the
 * sheet's rows, in every table that belongs to it, against the today the change was made on: the
 * sheet's today when the request making it began, so a change of the today itself (and the periods
 * it closes) is kept against the day being left (see {@link HistoryTransactionManager}); a later
 * change on the same today replaces what was kept for it.
 * The sheet as it stood at the end of a date is what the last change made on a today on or before
 * that date left, and {@link #restore} puts the sheet back to it inside a transaction that is then
 * rolled back.
 *
 * <p>The tables that belong to a sheet are found from the schema: those with a {@code sheet_id}
 * column, and those whose rows reference the rows of such a table, so a table added later is kept
 * with no change here.
 */
@Service
public class SheetHistory {

    /**
     * Put the sheet back to how it stood at the end of the date, with the date as its today: what the
     * last change made on a today on or before it left, or an empty sheet when there was none. Only
     * for a transaction that is rolled back afterwards.
     */
    public void restore(String sheet, LocalDate asOf) {
        List<byte[]> kept = jdbc.queryForList(
                "SELECT rows_data FROM sheet_history WHERE sheet_id = ? AND today <= ? ORDER BY seq DESC LIMIT 1",
                byte[].class, sheet, asOf);
        List<Table> all = tables();
        for (int i = all.size() - 1; i >= 0; i--) {
            Table table = all.get(i);
            jdbc.update("DELETE FROM " + table.name() + " WHERE " + table.ofSheet(), sheet);
        }
    /** Change the sheet's today; it has no audit line of its own: first a snapshot of each person's
     *  due-total on the day being left, then what it sets off (such as the periods it closes) and then
     *  the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id);
        Rollup.Snapshot before = rollup.snapshot(id);
        rollup.recordSnapshot(user, before);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(id, user, today));
        rollup.recordChanges(user, before);
        return saved;
    }

   *  is refused and takes no lock. A viewer's edit, and a claim another user's editor locks, are refused
   *  too, the editor showing its values without the lock; its save is refused. */
  protected async edit(claim: ClaimView): Promise<void> {
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.claimError.set(null);
    if (this.inClosedPeriod(claim.dueBy)) {
      this.claimError.set({ id: claim.id, message: 'This claim\'s due-by is inside a closed period, so it cannot be edited.' });
      return;
    }
    if (claim.status !== 'DRAFT') {
    const correction = amount.startsWith('-') && Number(amount) !== 0;
    if (correction && claim.corrects === null) {
      this.claimError.set({ id: claim.id, message: 'A negative amount is a correction: only a claim that corrects a settled claim can have one.' });
      return;
    }
    if (this.inlineSaving.has(claim.id)) return;
    this.inlineSaving.add(claim.id);
    try {
      const saved = await this.api.update(sheet.id, claim.id, { amount, date: claim.date, note: claim.note,
        corrects: correction ? claim.corrects : null, ref: claim.ref, tags: claim.tags.join(',') });
      if (this.session.sheet()?.id !== sheet.id) return;
      // The save released the user's own lock: an editor the user had open on the claim is closed.
      if (this.editingId() === claim.id) this.reset();
      this.saved.emit(saved);
    } catch (e) {
      if (this.session.sheet()?.id !== sheet.id) return;
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      const message = status === 403
        ? 'Your role may not edit a claim on this sheet.'
        : status === 423
        ? 'Someone else is editing this claim, so it cannot be saved until they save or cancel.'
        : status === 422
        ? 'A correction must name, by number, a settled claim of this person.'
        : this.inClosedPeriod(claim.dueBy)
        ? 'This claim\'s due-by is inside a closed period, so it cannot be edited.'

